sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_mBlack;
uniform float amzp_m1i;
uniform float amzp_m1o;
uniform float amzp_m2i;
uniform float amzp_m2o;
uniform float amzp_m3i;
uniform float amzp_m3o;
uniform float amzp_mWhite;
uniform float amzp_rBlack;
uniform float amzp_r1i;
uniform float amzp_r1o;
uniform float amzp_r2i;
uniform float amzp_r2o;
uniform float amzp_r3i;
uniform float amzp_r3o;
uniform float amzp_rWhite;
uniform float amzp_gBlack;
uniform float amzp_g1i;
uniform float amzp_g1o;
uniform float amzp_g2i;
uniform float amzp_g2o;
uniform float amzp_g3i;
uniform float amzp_g3o;
uniform float amzp_gWhite;
uniform float amzp_bBlack;
uniform float amzp_b1i;
uniform float amzp_b1o;
uniform float amzp_b2i;
uniform float amzp_b2o;
uniform float amzp_b3i;
uniform float amzp_b3o;
uniform float amzp_bWhite;
uniform float amzp_mixAmt;
    float herm(float x, float xa, float xb, float ya, float yb, float ma, float mb) {
        float h = xb - xa;
        float t = clamp((x - xa) / h, 0.0, 1.0);
        float t2 = t * t, t3 = t2 * t;
        return (2.0 * t3 - 3.0 * t2 + 1.0) * ya + (t3 - 2.0 * t2 + t) * h * ma + (-2.0 * t3 + 3.0 * t2) * yb + (t3 - t2) * h * mb;
    }
    float tan3(float d0, float d1, float h0, float h1) {
        if (d0 * d1 <= 0.0) return 0.0;
        float w1 = 2.0 * h1 + h0, w2 = h1 + 2.0 * h0;
        return (w1 + w2) / (w1 / d0 + w2 / d1);
    }
    float curve(float x, float y0, float2 p1, float2 p2, float2 p3, float y4) {
        float2 t;
        if (p1.x > p2.x) { t = p1; p1 = p2; p2 = t; }
        if (p2.x > p3.x) { t = p2; p2 = p3; p3 = t; }
        if (p1.x > p2.x) { t = p1; p1 = p2; p2 = t; }
        float x1 = clamp(p1.x, 0.01, 0.97);
        float x2 = clamp(p2.x, x1 + 0.01, 0.98);
        float x3 = clamp(p3.x, x2 + 0.01, 0.99);
        float h0 = x1, h1 = x2 - x1, h2 = x3 - x2, h3 = 1.0 - x3;
        float d0 = (p1.y - y0) / h0, d1 = (p2.y - p1.y) / h1, d2 = (p3.y - p2.y) / h2, d3 = (y4 - p3.y) / h3;
        float m1 = tan3(d0, d1, h0, h1), m2 = tan3(d1, d2, h1, h2), m3 = tan3(d2, d3, h2, h3);
        float m0 = d0, m4 = d3;
        x = clamp(x, 0.0, 1.0);
        float y;
        if (x < x1) y = herm(x, 0.0, x1, y0, p1.y, m0, m1);
        else if (x < x2) y = herm(x, x1, x2, p1.y, p2.y, m1, m2);
        else if (x < x3) y = herm(x, x2, x3, p2.y, p3.y, m2, m3);
        else y = herm(x, x3, 1.0, p3.y, y4, m3, m4);
        return clamp(y, 0.0, 1.0);
    }
    float cM(float v) { return curve(v, amzp_mBlack, float2(amzp_m1i, amzp_m1o), float2(amzp_m2i, amzp_m2o), float2(amzp_m3i, amzp_m3o), amzp_mWhite); }
    void amzRender() {
        float4 src = amzTexture(0, amzScreenNorm());
        float dev = abs(amzp_mBlack) + abs(amzp_mWhite - 1.0) + abs(amzp_m1i - 0.25) + abs(amzp_m1o - 0.25) + abs(amzp_m2i - 0.5) + abs(amzp_m2o - 0.5) + abs(amzp_m3i - 0.75) + abs(amzp_m3o - 0.75) + abs(amzp_rBlack) + abs(amzp_rWhite - 1.0) + abs(amzp_r1i - 0.25) + abs(amzp_r1o - 0.25) + abs(amzp_r2i - 0.5) + abs(amzp_r2o - 0.5) + abs(amzp_r3i - 0.75) + abs(amzp_r3o - 0.75) + abs(amzp_gBlack) + abs(amzp_gWhite - 1.0) + abs(amzp_g1i - 0.25) + abs(amzp_g1o - 0.25) + abs(amzp_g2i - 0.5) + abs(amzp_g2o - 0.5) + abs(amzp_g3i - 0.75) + abs(amzp_g3o - 0.75) + abs(amzp_bBlack) + abs(amzp_bWhite - 1.0) + abs(amzp_b1i - 0.25) + abs(amzp_b1o - 0.25) + abs(amzp_b2i - 0.5) + abs(amzp_b2o - 0.5) + abs(amzp_b3i - 0.75) + abs(amzp_b3o - 0.75);
        if (dev < 0.0001 || amzp_mixAmt <= 0.0001 || src.a <= 0.0001) { amzOutput = src; return; }
        float3 c = src.rgb / src.a;
        float3 y = float3(cM(c.r), cM(c.g), cM(c.b));
        y.r = curve(y.r, amzp_rBlack, float2(amzp_r1i, amzp_r1o), float2(amzp_r2i, amzp_r2o), float2(amzp_r3i, amzp_r3o), amzp_rWhite);
        y.g = curve(y.g, amzp_gBlack, float2(amzp_g1i, amzp_g1o), float2(amzp_g2i, amzp_g2o), float2(amzp_g3i, amzp_g3o), amzp_gWhite);
        y.b = curve(y.b, amzp_bBlack, float2(amzp_b1i, amzp_b1o), float2(amzp_b2i, amzp_b2o), float2(amzp_b3i, amzp_b3o), amzp_bWhite);
        float3 o = mix(c, y, clamp(amzp_mixAmt, 0.0, 1.0));
        amzOutput = float4(clamp(o, 0.0, 1.0) * src.a, src.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
